output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in one-cell-wide aisles flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shopperOnlyAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file_aisle",
    "text": "An agent must not enter an upper single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "shelvesOnBothSides"
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterShopperOnlyAisle": {
          "pre": {
            "and": [
              "N",
              "upperAisleMouth"
            ]
          },
          "post": "shopperOnlyAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterShopperOnlyAisle"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_upper_aisle_mouth",
    "text": "Upon arriving with a cart at the mouth of an upper single-file aisle, the agent is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "upperMouthWithCart": {
          "and": [
            "upperAisleMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "arriveAtUpperMouthWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "upperMouthWithCart"
        },
        "cartParkedAtUpperMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "upperAisleMouth",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtUpperMouthWithCart",
      "discharge": "cartParkedAtUpperMouth"
    }
  },
  {
    "id": "retrieve_cart_after_single_file_aisle",
    "text": "After returning from a cart-free single-file shelf aisle, the agent is obliged to retrieve the parked cart at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "shelvesOnBothSides"
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnFromShopperOnlyAisle": {
          "pre": {
            "and": [
              "S",
              "shopperOnlyAisle",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "upperAisleMouth"
        },
        "cartRetrievedAtUpperMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "upperAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromShopperOnlyAisle",
      "discharge": "cartRetrievedAtUpperMouth"
    }
  },
  {
    "id": "cart_drop_only_in_wide_staging_cells",
    "text": "Carts may only be parked in wide, non-shelf-adjacent staging cells rather than beside shelves or in constricted passages.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "notBesideShelf": {
          "not": "adjShelf"
        },
        "approvedCartParkingCell": {
          "and": [
            "wideHorizontalAisle",
            "notBesideShelf"
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "approvedCartParkingCell"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_at_entrance",
    "text": "After entering the store, the agent is obliged to take a cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": "at(1,7)"
      },
      "events": {
        "takeCartAtEntrance": {
          "pre": {
            "and": [
              "INTERACT",
              "entranceCartBay",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtEntrance"
    }
  },
  {
    "id": "exit_only_with_cart",
    "text": "The agent is prohibited from exiting the supermarket without the cart.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {
        "leaveStore": {
          "pre": {
            "and": [
              "EXIT",
              "exitCell"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveStore",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_wide_aisles_no_west",
    "text": "In broad horizontal circulation aisles, shopper traffic is one-way eastward, so westward movement is prohibited.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalCirculationAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "westwardTravelInWideAisle": {
          "pre": {
            "and": [
              "W",
              "wideHorizontalCirculationAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westwardTravelInWideAisle"
    }
  }
]
